import{_ as t,o as d,c as n,a2 as r}from"./chunks/framework.vLhlLNVn.js";const p=JSON.parse('{"title":"Datenpunkte","description":"","frontmatter":{"order":2,"adapter":"wled","editLink":"https://github.com/DrozmotiX/ioBroker.wled/edit/main/docs/de/03.referenz/02.datenpunkte.md"},"headers":[],"relativePath":"de/adapter/wled/referenz/datenpunkte.md","filePath":"de/adapter/wled/referenz/datenpunkte.md","lastUpdated":null}'),i={name:"de/adapter/wled/referenz/datenpunkte.md"};function a(o,e,s,c,l,h){return d(),n("div",null,[...e[0]||(e[0]=[r('<h1 id="datenpunkte" tabindex="-1">Datenpunkte <a class="header-anchor" href="#datenpunkte" aria-label="Permalink to &quot;Datenpunkte&quot;">​</a></h1><p><a id="individual-wled-states-mean"></a></p><h2 id="was-bedeuten-die-einzelnen-wled-datenpunkte" tabindex="-1">Was bedeuten die einzelnen WLED-Datenpunkte? <a class="header-anchor" href="#was-bedeuten-die-einzelnen-wled-datenpunkte" aria-label="Permalink to &quot;Was bedeuten die einzelnen WLED-Datenpunkte?&quot;">​</a></h2><p><strong>Kurz:</strong> Die Datenpunkte spiegeln die JSON-API von WLED. Fast jeder Schlüssel, den das Gerät meldet, wird ein Datenpunkt mit demselben Namen. Dazu kommen einige Datenpunkte, die der Adapter selbst anlegt, zum Beispiel <code>action</code> und <code>psave</code>. Die Tabellen unten nennen Typ, Schreibbarkeit, Bedeutung und Wertebereich.</p><p>Welche Datenpunkte es bei dir gibt, hängt von deiner WLED-Firmware ab. Der Adapter legt an, was das Gerät meldet. Name, Typ, Rolle und Schreibbarkeit holt er aus seiner Liste bekannter Schlüssel (<code>lib/stateAttr.js</code>). Kennt er einen Schlüssel nicht, legt er ihn trotzdem an, aber nur lesbar und mit dem Typ des Werts. Schreibst du einen Datenpunkt als Steuerbefehl (<code>ack=false</code>), schickt der Adapter ihn unter demselben Schlüssel an WLED.</p><p>Alle IDs beginnen mit <code>wled.0.&lt;Gerät&gt;</code>, wobei <code>&lt;Gerät&gt;</code> die MAC-Adresse des Geräts ohne Doppelpunkte ist. Die Spalte „Schreiben“ sagt, ob der Adapter einen geschriebenen Wert an das Gerät schickt.</p><h3 id="direkt-unter-dem-gerat" tabindex="-1">Direkt unter dem Gerät <a class="header-anchor" href="#direkt-unter-dem-gerat" aria-label="Permalink to &quot;Direkt unter dem Gerät&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Datenpunkt</th><th>Typ</th><th>Schreiben</th><th>Bedeutung</th><th>Werte</th></tr></thead><tbody><tr><td><code>on</code></td><td>boolean</td><td>ja</td><td>Hauptschalter des Geräts</td><td><code>true</code> / <code>false</code></td></tr><tr><td><code>bri</code></td><td>number</td><td>ja</td><td>Gesamthelligkeit</td><td>0 bis 255</td></tr><tr><td><code>transition</code></td><td>number</td><td>ja</td><td>Überblendzeit bei Farb- und Helligkeitswechseln, in 100 ms</td><td>0 bis 65535, <code>7</code> = 700 ms</td></tr><tr><td><code>tt</code></td><td>mixed</td><td>ja</td><td>Überblendzeit nur für den nächsten Befehl, in 100 ms</td><td>0 bis 65535</td></tr><tr><td><code>ps</code></td><td>number</td><td>ja</td><td>aktives Preset; schreiben lädt ein Preset</td><td>-1 bis 250, <code>-1</code> = keins</td></tr><tr><td><code>psave</code></td><td>mixed</td><td>ja</td><td>speichert den aktuellen Zustand als Preset</td><td>1 bis 250</td></tr><tr><td><code>pl</code></td><td>number</td><td>ja, wirkt aber nicht</td><td>laufende Playlist (nur Anzeige)</td><td>-1 bis 250, <code>-1</code> = keine</td></tr><tr><td><code>mainseg</code></td><td>number</td><td>ja</td><td>Hauptsegment, das UDP-Sync und Befehle ohne Segmentnummer nutzen</td><td>0 bis Segmentzahl - 1</td></tr><tr><td><code>lor</code></td><td>number</td><td>ja</td><td>Live-Override: Echtzeitdaten übersteuern</td><td><code>0</code> aus, <code>1</code> bis zum Ende der Live-Daten, <code>2</code> bis zum Neustart</td></tr><tr><td><code>time</code></td><td>mixed</td><td>nein</td><td>Uhrzeit setzen (Befehl ohne Rückmeldung)</td><td>Unix-Zeit in Sekunden</td></tr><tr><td><code>action</code></td><td>string</td><td>ja</td><td>kompletter JSON-Befehl an WLED</td><td>JSON-Text, z. B. <code>{&quot;on&quot;:true,&quot;bri&quot;:128}</code></td></tr><tr><td><code>rawCommand</code></td><td>string</td><td>ja</td><td>Befehl an die alte HTTP-API (<code>/win</code>)</td><td>Text, z. B. <code>T=2&amp;A=128</code></td></tr></tbody></table><p><code>tt</code>, <code>psave</code>, <code>time</code>, <code>action</code> und <code>rawCommand</code> meldet WLED nicht zurück. Der Adapter legt sie selbst an, ihr Wert zeigt nur, was zuletzt geschrieben wurde.</p><h3 id="nachtlicht-nl" tabindex="-1">Nachtlicht (<code>nl</code>) <a class="header-anchor" href="#nachtlicht-nl" aria-label="Permalink to &quot;Nachtlicht (`nl`)&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Datenpunkt</th><th>Typ</th><th>Schreiben</th><th>Bedeutung</th><th>Werte</th></tr></thead><tbody><tr><td><code>nl.on</code></td><td>boolean</td><td>ja</td><td>Nachtlicht läuft</td><td><code>true</code> / <code>false</code></td></tr><tr><td><code>nl.dur</code></td><td>number</td><td>ja</td><td>Dauer des Nachtlichts</td><td>1 bis 255 min</td></tr><tr><td><code>nl.mode</code></td><td>number</td><td>nein</td><td>Art des Nachtlichts</td><td><code>0</code> sofort, <code>1</code> dimmen, <code>2</code> Farbe überblenden, <code>3</code> Sonnenaufgang</td></tr><tr><td><code>nl.tbri</code></td><td>number</td><td>ja</td><td>Zielhelligkeit am Ende</td><td>0 bis 255</td></tr><tr><td><code>nl.rem</code></td><td>number</td><td>nein</td><td>Restzeit</td><td>Sekunden, <code>-1</code> = aus</td></tr></tbody></table><h3 id="udp-sync-udpn" tabindex="-1">UDP-Sync (<code>udpn</code>) <a class="header-anchor" href="#udp-sync-udpn" aria-label="Permalink to &quot;UDP-Sync (`udpn`)&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Datenpunkt</th><th>Typ</th><th>Schreiben</th><th>Bedeutung</th><th>Werte</th></tr></thead><tbody><tr><td><code>udpn.send</code></td><td>boolean</td><td>ja</td><td>bei Änderungen Sync-Pakete an andere WLED-Geräte senden</td><td><code>true</code> / <code>false</code></td></tr><tr><td><code>udpn.recv</code></td><td>boolean</td><td>ja</td><td>Sync-Pakete anderer Geräte empfangen</td><td><code>true</code> / <code>false</code></td></tr><tr><td><code>udpn.sgrp</code></td><td>number</td><td>nein</td><td>Sendegruppen als Bitfeld</td><td>0 bis 255</td></tr><tr><td><code>udpn.rgrp</code></td><td>number</td><td>nein</td><td>Empfangsgruppen als Bitfeld</td><td>0 bis 255</td></tr><tr><td><code>udpn.nn</code></td><td>mixed</td><td>ja</td><td>beim nächsten Befehl kein Sync-Paket senden</td><td><code>true</code> / <code>false</code></td></tr></tbody></table><p><code>sgrp</code> und <code>rgrp</code> gibt es nur mit WLED ab 0.14. Was die Datenpunkte bewirken und welche Grenzen sie haben, steht unter <a href="#use-udp-sync-state-udpn">Wie nutze ich den Datenpunkt für UDP-Sync (udpn)?</a>.</p><h3 id="segmente-seg-segment" tabindex="-1">Segmente (<code>seg.&lt;Segment&gt;</code>) <a class="header-anchor" href="#segmente-seg-segment" aria-label="Permalink to &quot;Segmente (`seg.&lt;Segment&gt;`)&quot;">​</a></h3><p>Für jedes Segment gibt es einen Kanal <code>seg.&lt;Segment&gt;</code>. Das erste Segment hat die Nummer <code>0</code>.</p><table tabindex="0"><thead><tr><th>Datenpunkt</th><th>Typ</th><th>Schreiben</th><th>Bedeutung</th><th>Werte</th></tr></thead><tbody><tr><td><code>id</code></td><td>number</td><td>nein</td><td>Nummer des Segments</td><td>0 bis Segmentzahl - 1</td></tr><tr><td><code>n</code></td><td>string</td><td>ja</td><td>Name des Segments</td><td>Text</td></tr><tr><td><code>start</code></td><td>number</td><td>ja</td><td>erste LED des Segments</td><td>0 bis LED-Zahl - 1</td></tr><tr><td><code>stop</code></td><td>number</td><td>ja</td><td>LED nach dem Segment (nicht mehr enthalten)</td><td>0 bis LED-Zahl</td></tr><tr><td><code>len</code></td><td>number</td><td>ja</td><td>Länge (<code>stop</code> - <code>start</code>)</td><td>0 bis LED-Zahl</td></tr><tr><td><code>grp</code></td><td>number</td><td>ja</td><td>Gruppierung: so viele LEDs zeigen dieselbe Farbe</td><td>0 bis 255</td></tr><tr><td><code>spc</code></td><td>number</td><td>ja</td><td>Abstand: so viele LEDs bleiben zwischen den Gruppen aus</td><td>0 bis 255</td></tr><tr><td><code>of</code></td><td>number</td><td>ja</td><td>Versatz: verschiebt den Anfang des Effekts</td><td>-Länge + 1 bis Länge</td></tr><tr><td><code>on</code></td><td>boolean</td><td>ja</td><td>Segment ein/aus</td><td><code>true</code> / <code>false</code></td></tr><tr><td><code>bri</code></td><td>number</td><td>ja</td><td>Helligkeit des Segments</td><td>0 bis 255</td></tr><tr><td><code>cct</code></td><td>number</td><td>ja</td><td>Farbtemperatur des Weißanteils</td><td>0 bis 255 oder 1900 bis 10091 K</td></tr><tr><td><code>frz</code></td><td>boolean</td><td>ja</td><td>Effekt anhalten (einfrieren)</td><td><code>true</code> / <code>false</code></td></tr><tr><td><code>col.0</code>, <code>col.1</code>, <code>col.2</code></td><td>mixed</td><td>ja</td><td>Primär-, Sekundär- und Tertiärfarbe als RGB-Text</td><td><code>[255,0,0]</code> oder <code>[255,0,0,0]</code> mit Weiß</td></tr><tr><td><code>col.0_HEX</code>, <code>col.1_HEX</code>, <code>col.2_HEX</code></td><td>mixed</td><td>ja</td><td>dieselben Farben als HEX</td><td><code>#rrggbb</code> oder <code>#rrggbbww</code></td></tr><tr><td><code>fx</code></td><td>number</td><td>ja</td><td>Effekt, mit Namensliste</td><td>Nummer, 0 bis Effektzahl - 1</td></tr><tr><td><code>sx</code></td><td>number</td><td>ja</td><td>Geschwindigkeit des Effekts</td><td>0 bis 255</td></tr><tr><td><code>ix</code></td><td>number</td><td>ja</td><td>Intensität des Effekts</td><td>0 bis 255</td></tr><tr><td><code>pal</code></td><td>number</td><td>ja</td><td>Palette, mit Namensliste</td><td>Nummer</td></tr><tr><td><code>c1</code>, <code>c2</code>, <code>c3</code></td><td>string</td><td>ja</td><td>Zusatzregler des Effekts</td><td><code>c1</code>, <code>c2</code>: 0 bis 255, <code>c3</code>: 0 bis 31</td></tr><tr><td><code>o1</code>, <code>o2</code>, <code>o3</code></td><td>boolean</td><td>nein</td><td>Zusatzschalter des Effekts</td><td><code>true</code> / <code>false</code></td></tr><tr><td><code>sel</code></td><td>boolean</td><td>ja</td><td>Segment ist ausgewählt</td><td><code>true</code> / <code>false</code></td></tr><tr><td><code>rev</code></td><td>boolean</td><td>ja</td><td>Effekt läuft rückwärts</td><td><code>true</code> / <code>false</code></td></tr><tr><td><code>mi</code></td><td>boolean</td><td>nein (ab v0.9.3 ja)</td><td>Segment spiegeln</td><td><code>true</code> / <code>false</code></td></tr><tr><td><code>si</code></td><td>number</td><td>nein</td><td>Klangsimulation für Audio-Effekte</td><td>0 bis 3</td></tr><tr><td><code>m12</code></td><td>number</td><td>nein</td><td>„Expand 1D FX“ bei Matrizen</td><td>0 bis 4</td></tr><tr><td><code>set</code></td><td>number</td><td>nein</td><td>Gruppe des Segments in der WLED-Oberfläche</td><td>0 bis 3</td></tr></tbody></table><p>Ein geschriebener Segment-Datenpunkt geht als <code>{&quot;seg&quot;:{&quot;id&quot;:&lt;Segment&gt;,&quot;&lt;Schlüssel&gt;&quot;:&lt;Wert&gt;}}</code> an WLED. Schreibst du eine Farbe, schickt der Adapter alle drei Farben des Segments mit. Matrix-Schlüssel wie <code>startY</code>, <code>stopY</code>, <code>rY</code>, <code>mY</code> und <code>tp</code> kennt der Adapter nicht, sie erscheinen bei 2D-Aufbauten nur lesbar.</p><p><strong>Ab v0.9.3:</strong> <code>seg.&lt;Segment&gt;.mi</code> ist schreibbar (<a href="https://github.com/DrozmotiX/ioBroker.wled/issues/918" target="_blank" rel="noreferrer">#918</a>). Die Segment-Kanäle tragen die Segment-ID aus WLED, und Segmente, die du in WLED anlegst oder löschst, zieht der Adapter ohne Neustart nach (<a href="https://github.com/DrozmotiX/ioBroker.wled/issues/909" target="_blank" rel="noreferrer">#909</a>).</p><h3 id="gerateinformationen-info" tabindex="-1">Geräteinformationen (<code>_info</code>) <a class="header-anchor" href="#gerateinformationen-info" aria-label="Permalink to &quot;Geräteinformationen (`_info`)&quot;">​</a></h3><p>Alles unter <code>_info</code> ist nur lesbar. Die wichtigsten Werte:</p><table tabindex="0"><thead><tr><th>Datenpunkt</th><th>Typ</th><th>Bedeutung</th></tr></thead><tbody><tr><td><code>_info._online</code></td><td>boolean</td><td>Gerät ist für den Adapter erreichbar</td></tr><tr><td><code>_info.name</code></td><td>mixed</td><td>Name des Geräts in WLED</td></tr><tr><td><code>_info.ver</code>, <code>_info.vid</code></td><td>string, number</td><td>Firmware-Version und Build-Nummer</td></tr><tr><td><code>_info.ip</code>, <code>_info.mac</code></td><td>string</td><td>IP- und MAC-Adresse</td></tr><tr><td><code>_info.leds.count</code></td><td>number</td><td>Zahl der LEDs</td></tr><tr><td><code>_info.leds.pwr</code>, <code>_info.leds.maxpwr</code></td><td>number</td><td>aktueller Strom und Stromgrenze in mA (0 = Begrenzung aus)</td></tr><tr><td><code>_info.leds.fps</code></td><td>number</td><td>Bilder pro Sekunde</td></tr><tr><td><code>_info.leds.maxseg</code></td><td>number</td><td>höchste Segmentzahl der Firmware</td></tr><tr><td><code>_info.fxcount</code>, <code>_info.palcount</code></td><td>mixed</td><td>Zahl der Effekte und Paletten</td></tr><tr><td><code>_info.live</code>, <code>_info.lm</code>, <code>_info.lip</code></td><td>boolean, string, string</td><td>Gerät empfängt gerade Echtzeitdaten, von welcher Quelle und IP</td></tr><tr><td><code>_info.ws</code></td><td>number</td><td>Zahl der WebSocket-Verbindungen zum Gerät, <code>-1</code> = keine Unterstützung</td></tr><tr><td><code>_info.wifi.signal</code>, <code>_info.wifi.rssi</code></td><td>number</td><td>WLAN-Empfang in % und dBm</td></tr><tr><td><code>_info.freeheap</code>, <code>_info.uptime</code></td><td>number</td><td>freier Speicher in Byte, Laufzeit seit dem Start in s</td></tr><tr><td><code>_info.time</code></td><td>mixed</td><td>Uhrzeit des Geräts als Text</td></tr></tbody></table><p>Dazu kommt <code>wled.0.info.connection</code> für die ganze Instanz. Was <code>_online</code> und <code>info.connection</code> genau anzeigen, steht unter <a href="./../hintergrund/verbindung-und-aktualisierung#tell-whether-device-really-online">Woran sehe ich, ob ein Gerät wirklich online ist?</a>.</p><p><strong>Ab v0.9.3:</strong> Der Adapter legt für jedes Gerät den Knopf <code>rb</code> (Neustart) an. <code>time</code> ist schreibbar und setzt die Uhrzeit des Geräts (<a href="https://github.com/DrozmotiX/ioBroker.wled/issues/911" target="_blank" rel="noreferrer">#911</a>, <a href="https://github.com/DrozmotiX/ioBroker.wled/issues/919" target="_blank" rel="noreferrer">#919</a>).</p><p><strong>Ab v0.10.0:</strong> Diese Datenpunkte kommen dazu (<a href="https://github.com/DrozmotiX/ioBroker.wled/issues/926" target="_blank" rel="noreferrer">#926</a>, <a href="https://github.com/DrozmotiX/ioBroker.wled/issues/328" target="_blank" rel="noreferrer">#328</a>, <a href="https://github.com/DrozmotiX/ioBroker.wled/issues/929" target="_blank" rel="noreferrer">#929</a>, <a href="https://github.com/DrozmotiX/ioBroker.wled/issues/930" target="_blank" rel="noreferrer">#930</a>):</p><table tabindex="0"><thead><tr><th>Datenpunkt</th><th>Typ</th><th>Schreiben</th><th>Bedeutung</th><th>Werte</th></tr></thead><tbody><tr><td><code>bundleCommands</code></td><td>boolean</td><td>ja</td><td>Befehle kurz hintereinander zu einem Befehl bündeln</td><td><code>true</code> (Standard) / <code>false</code></td></tr><tr><td><code>light.on</code></td><td>boolean</td><td>ja</td><td>Gerät ein/aus, für den iot-Adapter</td><td><code>true</code> / <code>false</code></td></tr><tr><td><code>light.dimmer</code></td><td>number</td><td>ja</td><td>Gesamthelligkeit in Prozent</td><td>0 bis 100 %</td></tr><tr><td><code>light.rgb</code></td><td>string</td><td>ja</td><td>Primärfarbe des Hauptsegments</td><td><code>#rrggbb</code></td></tr><tr><td><code>seg.&lt;Segment&gt;.last.col</code></td><td>string</td><td>nein</td><td>Farben vor der letzten Farbänderung</td><td>JSON-Text wie <code>[[255,0,0],[0,0,0],[0,0,0]]</code></td></tr><tr><td><code>seg.&lt;Segment&gt;.last.fx</code></td><td>number</td><td>nein</td><td>Effekt vor dem letzten Effektwechsel</td><td>Nummer</td></tr><tr><td><code>seg.&lt;Segment&gt;.last.pal</code></td><td>number</td><td>nein</td><td>Palette vor dem letzten Palettenwechsel</td><td>Nummer</td></tr><tr><td><code>seg.&lt;Segment&gt;.last.restore</code></td><td>boolean</td><td>ja</td><td>Knopf: setzt Farben, Effekt und Palette von davor wieder</td><td><code>true</code></td></tr><tr><td><code>_info.u.&lt;Name&gt;</code></td><td>number, boolean oder string</td><td>nein</td><td>Wert eines WLED-Usermods, zum Beispiel ein Sensor</td><td>wie vom Usermod gemeldet, Einheit im Objekt</td></tr></tbody></table><p><code>light.dimmer</code> rechnet beim Schreiben auf <code>bri</code> von 0 bis 255 um und schaltet das Gerät bei mehr als 0 % ein. <code>light.rgb</code> lässt den Weißkanal unverändert.</p><p><strong>Siehe auch:</strong></p><ul><li><a href="./../erste-schritte/erste-steuerung#state-use-switch-off-whole">Welchen Datenpunkt nehme ich zum Ein- und Ausschalten, das ganze Gerät oder nur ein Segment?</a></li><li><a href="./../anleitungen/befehle-an-wled#send-complete-json-command-wled">Wie sende ich einen kompletten JSON-Befehl an WLED aus ioBroker?</a></li><li><a href="./../anleitungen/effekte-und-presets#start-wled-playlist-through-adapter">Wie starte ich eine WLED-Playlist über den Adapter?</a></li><li><a href="./log-meldungen#warning-state-attribute-definition-missing">Was bedeutet die Warnung &quot;State attribute definition missing&quot;?</a></li><li><a href="./../hintergrund/werte-und-integrationen#usermod-buttons-gpio-states">Wie bekomme ich Usermod-Werte, Taster, Kontakte oder GPIO-Pins als Datenpunkt?</a></li></ul><p><a id="write-effect-parameters-c1-c3"></a></p><h2 id="wie-schreibe-ich-die-effekt-parameter-c1-bis-c3" tabindex="-1">Wie schreibe ich die Effekt-Parameter c1 bis c3? <a class="header-anchor" href="#wie-schreibe-ich-die-effekt-parameter-c1-bis-c3" aria-label="Permalink to &quot;Wie schreibe ich die Effekt-Parameter c1 bis c3?&quot;">​</a></h2><p><strong>Kurz:</strong> Die Zusatzregler eines Effekts liegen je Segment unter <code>wled.0.&lt;Gerät&gt;.seg.&lt;Segment&gt;.c1</code>, <code>c2</code> und <code>c3</code>. Du schreibst sie wie jeden anderen Segment-Datenpunkt als Steuerbefehl mit einer Zahl. Schreibbar sind sie ab v0.7.3, im Grundstand v0.9.2 also immer.</p><p>In der WLED-Oberfläche erscheinen diese Regler unter wechselnden Namen, je nach Effekt. Beim Effekt „Scrolling Text“ zum Beispiel heißt <code>c1</code> „Trail“. Welcher Regler bei welchem Effekt was bewirkt und ob er überhaupt genutzt wird, legt die Firmware für jeden Effekt fest.</p><table tabindex="0"><thead><tr><th>Datenpunkt</th><th>Werte</th><th>Bedeutung</th></tr></thead><tbody><tr><td><code>seg.&lt;Segment&gt;.c1</code></td><td>0 bis 255</td><td>Zusatzregler 1 des Effekts</td></tr><tr><td><code>seg.&lt;Segment&gt;.c2</code></td><td>0 bis 255</td><td>Zusatzregler 2 des Effekts</td></tr><tr><td><code>seg.&lt;Segment&gt;.c3</code></td><td>0 bis 31</td><td>Zusatzregler 3 des Effekts</td></tr></tbody></table><h3 id="so-gehst-du-vor" tabindex="-1">So gehst du vor <a class="header-anchor" href="#so-gehst-du-vor" aria-label="Permalink to &quot;So gehst du vor&quot;">​</a></h3><ol><li>Stell in WLED den Effekt ein und schau in der WLED-Oberfläche, welcher Regler welchen Namen hat. Der erste Zusatzregler nach Geschwindigkeit und Intensität ist <code>c1</code>.</li><li>Schreib den Wert als Steuerbefehl, zum Beispiel <code>setState(&#39;wled.0.&lt;Gerät&gt;.seg.0.c1&#39;, 0);</code>.</li><li>Der Regler in der WLED-Oberfläche springt auf den neuen Wert.</li></ol><p>Der Adapter schickt dann <code>{&quot;seg&quot;:{&quot;id&quot;:0,&quot;c1&quot;:0}}</code> an das Gerät. WLED nimmt die Zahl auch als Text an, <code>&quot;0&quot;</code> wirkt also genauso.</p><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p><code>c1</code> bis <code>c3</code> haben im Adapter den Typ <code>string</code>, WLED meldet aber Zahlen. Darum kann ioBroker beim Aktualisieren eine Warnung zum Datentyp ins Log schreiben („has to be type &quot;string&quot; but received type &quot;number&quot;“). Sie ist harmlos, die Werte kommen trotzdem an.</p></div><h3 id="die-schalter-o1-bis-o3" tabindex="-1">Die Schalter o1 bis o3 <a class="header-anchor" href="#die-schalter-o1-bis-o3" aria-label="Permalink to &quot;Die Schalter o1 bis o3&quot;">​</a></h3><p>Neben den Reglern haben manche Effekte bis zu drei Zusatzschalter, <code>o1</code> bis <code>o3</code>. Der Adapter zeigt sie unter <code>seg.&lt;Segment&gt;.o1</code> bis <code>o3</code> an, schickt geschriebene Werte aber nicht an das Gerät. Willst du einen Schalter setzen, nimm den Datenpunkt <code>action</code> mit einem JSON-Befehl:</p><div class="language-js vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">js</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">setState</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;wled.0.&lt;Gerät&gt;.action&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">JSON</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">stringify</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">({ seg: { id: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">0</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, o1: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> } }));</span></span></code></pre></div><p><strong>Bis v0.7.2:</strong> <code>c1</code> bis <code>c3</code> waren nur lesbar. Ab v0.7.3 sind alle Segment-Datenpunkte mit Schreibrecht beschreibbar, darunter <code>c1</code> bis <code>c3</code> (<a href="https://github.com/DrozmotiX/ioBroker.wled/issues/688" target="_blank" rel="noreferrer">#688</a>).</p><p><strong>Siehe auch:</strong></p><ul><li><a href="./../anleitungen/effekte-und-presets#change-text-scrolling-text-effect">Wie ändere ich den Text des Effekts &quot;Scrolling Text&quot; oder den Segmentnamen?</a></li><li><a href="./../anleitungen/befehle-an-wled#send-complete-json-command-wled">Wie sende ich einen kompletten JSON-Befehl an WLED aus ioBroker?</a></li><li><a href="#individual-wled-states-mean">Was bedeuten die einzelnen WLED-Datenpunkte?</a></li></ul><p><a id="use-udp-sync-state-udpn"></a></p><h2 id="wie-nutze-ich-den-datenpunkt-fur-udp-sync-udpn" tabindex="-1">Wie nutze ich den Datenpunkt für UDP-Sync (udpn)? <a class="header-anchor" href="#wie-nutze-ich-den-datenpunkt-fur-udp-sync-udpn" aria-label="Permalink to &quot;Wie nutze ich den Datenpunkt für UDP-Sync (udpn)?&quot;">​</a></h2><p><strong>Kurz:</strong> Unter <code>wled.0.&lt;Gerät&gt;.udpn</code> liegen die Schalter für den Sync zwischen WLED-Geräten. <code>udpn.send</code> legt fest, ob das Gerät seine Änderungen an andere WLED-Geräte im Netz weitergibt, <code>udpn.recv</code>, ob es Änderungen anderer Geräte übernimmt. Beide sind im Grundstand v0.9.2 schreibbar, und schon der älteste Stand im Repository (v0.5.2) hat sie.</p><h3 id="was-der-sync-macht" tabindex="-1">Was der Sync macht <a class="header-anchor" href="#was-der-sync-macht" aria-label="Permalink to &quot;Was der Sync macht&quot;">​</a></h3><p>WLED-Geräte können sich über UDP gegenseitig abgleichen. Schaltest du ein Gerät mit <code>send</code> ein, übernehmen alle Geräte mit <code>recv</code> im selben Netz und auf demselben UDP-Port Ein/Aus, Helligkeit, Farbe und Effekt. Was genau übernommen wird, stellst du in WLED unter „Config“ › „Sync Interfaces“ ein. <code>udpn.send</code> entspricht dem Knopf „Sync“ in der WLED-Oberfläche.</p><p>Das gilt auch für Befehle aus ioBroker. Hat ein Gerät <code>send</code> an, gibt es jeden Befehl des Adapters an die anderen Geräte weiter.</p><h3 id="die-datenpunkte" tabindex="-1">Die Datenpunkte <a class="header-anchor" href="#die-datenpunkte" aria-label="Permalink to &quot;Die Datenpunkte&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Datenpunkt</th><th>Schreiben</th><th>Bedeutung</th></tr></thead><tbody><tr><td><code>udpn.send</code></td><td>ja</td><td><code>true</code>: Änderungen an andere Geräte senden</td></tr><tr><td><code>udpn.recv</code></td><td>ja (siehe unten)</td><td><code>true</code>: Änderungen anderer Geräte übernehmen</td></tr><tr><td><code>udpn.nn</code></td><td>ja</td><td>nur für einen einzelnen Befehl nichts senden</td></tr><tr><td><code>udpn.sgrp</code>, <code>udpn.rgrp</code></td><td>nein</td><td>Sende- und Empfangsgruppen als Bitfeld, ab WLED 0.14</td></tr></tbody></table><h3 id="so-gehst-du-vor-1" tabindex="-1">So gehst du vor <a class="header-anchor" href="#so-gehst-du-vor-1" aria-label="Permalink to &quot;So gehst du vor&quot;">​</a></h3><p>Ein typischer Fall: Mehrere Streifen sollen sich immer gleich verhalten, aber nur einer wird aus ioBroker gesteuert.</p><ol><li>Setz beim Hauptgerät <code>wled.0.&lt;Hauptgerät&gt;.udpn.send</code> auf <code>true</code>.</li><li>Setz bei den anderen Geräten <code>wled.0.&lt;Gerät&gt;.udpn.recv</code> auf <code>true</code>.</li><li>Schalte das Hauptgerät aus ioBroker, zum Beispiel über <code>on</code>. Die anderen Streifen folgen.</li></ol><p>Umgekehrt schaltest du <code>udpn.send</code> aus, wenn ein Gerät ohne Wirkung auf die anderen gesteuert werden soll.</p><h3 id="einen-einzelnen-befehl-ohne-sync-senden-nn" tabindex="-1">Einen einzelnen Befehl ohne Sync senden (<code>nn</code>) <a class="header-anchor" href="#einen-einzelnen-befehl-ohne-sync-senden-nn" aria-label="Permalink to &quot;Einen einzelnen Befehl ohne Sync senden (`nn`)&quot;">​</a></h3><p><code>udpn.nn</code> gilt laut WLED nur für den Befehl, in dem es steht. Schreibst du <code>udpn.nn</code> allein, schickt der Adapter <code>{&quot;udpn&quot;:{&quot;nn&quot;:true}}</code> als eigenen Befehl, und es hat keine Wirkung. Nimm stattdessen den Datenpunkt <code>action</code> und schick <code>nn</code> zusammen mit dem eigentlichen Befehl:</p><div class="language-js vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">js</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">setState</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;wled.0.&lt;Gerät&gt;.action&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">JSON</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">stringify</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">({ on: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, bri: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">128</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, udpn: { nn: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> } }));</span></span></code></pre></div><div class="important custom-block github-alert"><p class="custom-block-title">IMPORTANT</p><p><strong>Ab WLED 0.15</strong> wertet die Firmware ein geschriebenes <code>udpn.recv</code> nicht mehr aus. <code>recv</code> zeigt dort nur noch an, ob mindestens eine Empfangsgruppe aktiv ist. Den Empfang schaltest du dann über die Empfangsgruppen, zum Beispiel aus mit <code>{&quot;udpn&quot;:{&quot;rgrp&quot;:0}}</code> und für Gruppe 1 wieder ein mit <code>{&quot;udpn&quot;:{&quot;rgrp&quot;:1}}</code>, jeweils über den Datenpunkt <code>action</code>. <code>udpn.send</code> funktioniert weiter wie oben.</p></div><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p>Den Kanal <code>udpn</code> legt der Adapter nur an, wenn das Gerät ihn meldet. <code>udpn.nn</code> legt er immer an, weil WLED <code>nn</code> nie zurückmeldet.</p></div><p><strong>Siehe auch:</strong></p><ul><li><a href="./../fehlerbehebung/segmente-und-synchronisation#one-wled-device-take-over">Warum übernimmt ein WLED-Gerät die Einstellungen eines anderen?</a></li><li><a href="./../anleitungen/befehle-an-wled#send-complete-json-command-wled">Wie sende ich einen kompletten JSON-Befehl an WLED aus ioBroker?</a></li><li><a href="#individual-wled-states-mean">Was bedeuten die einzelnen WLED-Datenpunkte?</a></li></ul><p><a id="hue-sync-reboot-realtime-udp"></a></p><h2 id="was-machen-hue-sync-neustart-und-realtime-udp-hp-rb-rd" tabindex="-1">Was machen Hue Sync, Neustart und Realtime-UDP (hp, rb, rd)? <a class="header-anchor" href="#was-machen-hue-sync-neustart-und-realtime-udp-hp-rb-rd" aria-label="Permalink to &quot;Was machen Hue Sync, Neustart und Realtime-UDP (hp, rb, rd)?&quot;">​</a></h2><p><strong>Kurz:</strong> Bis v0.9.2 erscheinen <code>hp</code>, <code>rb</code> und <code>rd</code> auf echten Geräten nicht, obwohl der Changelog von v0.9.0 sie ankündigt. Ab v0.9.3 legt der Adapter den Neustart-Knopf <code>rb</code> für jedes Gerät an. <code>hp</code> und <code>rd</code> erscheinen weiter nur, wenn das Gerät sie meldet, und die übliche WLED-Firmware tut das nicht. Den Neustart löst du bis dahin über den Datenpunkt <code>action</code> aus.</p><h3 id="was-die-drei-datenpunkte-bedeuten-sollen" tabindex="-1">Was die drei Datenpunkte bedeuten sollen <a class="header-anchor" href="#was-die-drei-datenpunkte-bedeuten-sollen" aria-label="Permalink to &quot;Was die drei Datenpunkte bedeuten sollen&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Datenpunkt</th><th>Typ</th><th>Bedeutung</th><th>Werte</th></tr></thead><tbody><tr><td><code>rb</code></td><td>boolean, Knopf</td><td>startet das WLED-Gerät sofort neu</td><td><code>true</code></td></tr><tr><td><code>hp</code></td><td>number</td><td>Hue-Sync: Nummer der Philips-Hue-Lampe, deren Farbe WLED übernimmt</td><td>0 bis 99, <code>0</code> = aus</td></tr><tr><td><code>rd</code></td><td>boolean</td><td>Echtzeitdaten per UDP empfangen</td><td><code>true</code> / <code>false</code></td></tr></tbody></table><h3 id="warum-sie-fehlen" tabindex="-1">Warum sie fehlen <a class="header-anchor" href="#warum-sie-fehlen" aria-label="Permalink to &quot;Warum sie fehlen&quot;">​</a></h3><p>Der Adapter legt Datenpunkte für Werte an, die das Gerät meldet. Befehle, die WLED annimmt, aber nie zurückmeldet, muss er selbst anlegen, wie bei <code>tt</code> und <code>psave</code>. Für <code>hp</code>, <code>rb</code> und <code>rd</code> steht in v0.9.2 nur die Beschreibung im Code, angelegt werden sie nicht. WLED meldet <code>rb</code> nie zurück, und <code>hp</code> und <code>rd</code> kommen in der JSON-API der Firmware 0.12 bis 0.15 gar nicht vor.</p><h3 id="das-gerat-aus-iobroker-neu-starten" tabindex="-1">Das Gerät aus ioBroker neu starten <a class="header-anchor" href="#das-gerat-aus-iobroker-neu-starten" aria-label="Permalink to &quot;Das Gerät aus ioBroker neu starten&quot;">​</a></h3><p>Bis v0.9.2 schreibst du den Befehl in den Datenpunkt <code>action</code>:</p><div class="language-js vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">js</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">setState</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;wled.0.&lt;Gerät&gt;.action&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">JSON</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">stringify</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">({ rb: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> }));</span></span></code></pre></div><p>Das Gerät startet sofort neu, ist für einige Sekunden nicht erreichbar und verbindet sich danach wieder mit dem Adapter.</p><p><strong>Ab v0.9.3:</strong> Es gibt den Knopf <code>wled.0.&lt;Gerät&gt;.rb</code>. Setz ihn auf <code>true</code>, und das Gerät startet neu (<a href="https://github.com/DrozmotiX/ioBroker.wled/issues/911" target="_blank" rel="noreferrer">#911</a>). In VIS bindest du ihn an eine Taste.</p><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p>WLED führt <code>rb</code> nicht aus, wenn im selben Befehl <code>psave</code> steht. Schick Neustart und Speichern darum getrennt.</p></div><h3 id="hue-sync-und-echtzeit-udp-ohne-diese-datenpunkte" tabindex="-1">Hue-Sync und Echtzeit-UDP ohne diese Datenpunkte <a class="header-anchor" href="#hue-sync-und-echtzeit-udp-ohne-diese-datenpunkte" aria-label="Permalink to &quot;Hue-Sync und Echtzeit-UDP ohne diese Datenpunkte&quot;">​</a></h3><ul><li><strong>Hue-Sync</strong> stellst du in der WLED-Oberfläche unter „Config“ › „Sync Interfaces“ im Bereich für Philips Hue ein.</li><li><strong>Echtzeitdaten</strong> (zum Beispiel von Hyperion) nimmt WLED nach seinen Sync-Einstellungen an. Ob gerade Echtzeitdaten ankommen, siehst du an <code>_info.live</code>, die Quelle an <code>_info.lm</code> und <code>_info.lip</code>. Mit <code>lor</code> übersteuerst du die Echtzeitdaten aus ioBroker: <code>1</code> bis zum Ende der Live-Daten, <code>2</code> bis zum nächsten Neustart, <code>0</code> aus.</li></ul><p><strong>Siehe auch:</strong></p><ul><li><a href="./../anleitungen/befehle-an-wled#send-complete-json-command-wled">Wie sende ich einen kompletten JSON-Befehl an WLED aus ioBroker?</a></li><li><a href="./../fehlerbehebung/verbindung-und-start#wled-shown-offline-after-restart">Warum wird WLED nach Neustart oder Update als offline angezeigt und verbindet sich lange nicht?</a></li><li><a href="#individual-wled-states-mean">Was bedeuten die einzelnen WLED-Datenpunkte?</a></li></ul>',80)])])}const b=t(i,[["render",a]]);export{p as __pageData,b as default};
